fn solve(x: i32) -> i32 {
    // Convert x to a string to easily extract the digit and its length
    let x_str = x.to_string();
    let d = x_str.chars().next().unwrap().to_digit(10).unwrap() as i32; // The digit
    let k = x_str.len() as i32; // The length of the number

    let mut score = 0;

    // Calculate the score for all boring apartment numbers with digits less than d
    for digit in 1..d {
        // Each digit contributes 1 + 2 + 3 + 4 presses for lengths 1 to 4
        score += digit * 4; // 1 press for 1-digit, 2 for 2-digit, 3 for 3-digit, 4 for 4-digit
    }

    // Now add the presses for the current digit d up to length k
    score += d * k; // d contributes k presses for the number of length k

    score
}